CREATE POLICY portfolio_public_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='worker-portfolio'); CREATE POLICY worker_upload_own ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id IN ('worker-portfolio','worker-documents') AND (storage.foldername(name))[1]=auth.uid()::text AND public.has_role(auth.uid(),'worker')); CREATE POLICY worker_document_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='worker-documents' AND (storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY worker_upload_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id IN ('worker-portfolio','worker-documents') AND (storage.foldername(name))[1]=auth.uid()::text); CREATE OR REPLACE FUNCTION public.pending_document() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM set_config('skillconnect.document_update','true',true); UPDATE public.workers SET verification_status='Pending verification' WHERE user_id=NEW.user_id AND NOT is_sample AND NOT verified; PERFORM set_config('skillconnect.document_update','false',true); RETURN NEW; END $$; CREATE OR REPLACE FUNCTION public.protect_worker_fields() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.role()='authenticated' AND (NEW.is_sample IS DISTINCT FROM OLD.is_sample OR NEW.verified IS DISTINCT FROM OLD.verified OR NEW.rating IS DISTINCT FROM OLD.rating OR NEW.reviews IS DISTINCT FROM OLD.reviews OR (NEW.verification_status IS DISTINCT FROM OLD.verification_status AND coalesce(current_setting('skillconnect.document_update',true),'false')<>'true') OR NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id) THEN RAISE EXCEPTION 'Protected worker fields cannot be changed'; END IF; RETURN NEW; END $$; CREATE OR REPLACE FUNCTION public.validate_worker_registration() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT NEW.is_sample AND (char_length(trim(NEW.area))=0 OR char_length(trim(NEW.city))=0 OR char_length(trim(NEW.name))=0) THEN RAISE EXCEPTION 'Name, city and locality are required'; END IF; IF NEW.category_id NOT IN ('driver','plumber','carpenter','loader','mehndi','repair','photographer','painter','cleaner','electrician','tailor','caregiver','catering','construction','goldsmith','handicraft','weaver','gardener','beekeeper','laundry','wedding','welder','pest','event','dairy','decorator','musician','sculptor','tutor','entrepreneur') THEN RAISE EXCEPTION 'Choose a supported category'; END IF; RETURN NEW; END $$; CREATE TRIGGER worker_registration_check BEFORE INSERT OR UPDATE ON public.workers FOR EACH ROW EXECUTE FUNCTION public.validate_worker_registration();